  inputs: [dec("daily_demand", ["Average daily demand", "গড় দৈনিক চাহিদা"], { min: "0" }), int("lead_time_days", ["Supplier lead time (days)", "সরবরাহ লিড টাইম (দিন)"], { min: "0", max: "365" }), dec("safety_stock_qty", ["Safety stock (units)", "নিরাপত্তা স্টক (একক)"], { min: "0" }), opt(dec("on_hand_qty", ["Stock on hand (units)", "হাতে মজুত"], { min: "0" })), opt(money("unit_cost", ["Unit cost", "একক খরচ"])), opt(pct("annual_carrying_rate_pct", ["Annual carrying cost % of value", "বার্ষিক বহন খরচ %"], { max: "200" })), opt(money("order_cost", ["Cost per order", "প্রতি অর্ডার খরচ"])), opt(dec("annual_demand", ["Annual demand (units)", "বার্ষিক চাহিদা"], { min: "0" }))],
  outputs: [out("reorder_point", ["Reorder point (units)", "রিঅর্ডার পয়েন্ট"], 4), out("days_of_cover", ["Days of cover", "কভার দিন"], 4), out("economic_order_qty", ["EOQ (units)", "EOQ"], 4), out("annual_carrying_cost_of_safety_stock", ["Annual carrying cost of safety stock", "সেফটি স্টকের বার্ষিক বহন খরচ"])], status: "implemented_tested",
